-- BASE TABLE `import_log`
CREATE TABLE "import_log" (
  "id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "source_file" text NOT NULL,
  "imported_at" datetime NOT NULL,
  "record_count" int NOT NULL,
  "inserted_count" int NOT NULL,
  "skipped_count" int NOT NULL,
  PRIMARY KEY ("id")
);

-- BASE TABLE `reminders`
CREATE TABLE "reminders" (
  "id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "user_id" bigint unsigned NOT NULL,
  "title" varchar(255) NOT NULL DEFAULT 'Ticket Reminder',
  "sale_at" datetime NOT NULL,
  "offsets_minutes" json NOT NULL,
  "enabled" tinyint(1) NOT NULL DEFAULT '1',
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  KEY "idx_reminders_user_id" ("user_id"),
  CONSTRAINT "fk_reminders_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

-- BASE TABLE `sales_channels`
CREATE TABLE "sales_channels" (
  "channel_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "event_id" bigint unsigned NOT NULL,
  "platform" varchar(100) DEFAULT NULL,
  "channel_type" varchar(50) DEFAULT NULL,
  "start_date" date DEFAULT NULL,
  "start_time" time DEFAULT NULL,
  "end_date" date DEFAULT NULL,
  "end_time" time DEFAULT NULL,
  "sales_status" varchar(50) DEFAULT NULL,
  "notes" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("channel_id"),
  KEY "fk_channel_event" ("event_id"),
  CONSTRAINT "fk_channel_event" FOREIGN KEY ("event_id") REFERENCES "events" ("event_id") ON DELETE CASCADE
);
