-- BASE TABLE `ticket_pricing`
CREATE TABLE "ticket_pricing" (
  "price_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "event_id" bigint unsigned NOT NULL,
  "tier_name" varchar(100) DEFAULT NULL,
  "price_amount" decimal(10,0) DEFAULT NULL,
  "max_quantity" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("price_id"),
  KEY "fk_pricing_event" ("event_id"),
  CONSTRAINT "fk_pricing_event" FOREIGN KEY ("event_id") REFERENCES "events" ("event_id") ON DELETE CASCADE
);

-- BASE TABLE `users`
CREATE TABLE "users" (
  "id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "email" varchar(255) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE KEY "uniq_users_email" ("email")
);

-- BASE TABLE `venue_locations`
CREATE TABLE "venue_locations" (
  "location_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "venue_id" bigint unsigned NOT NULL,
  "city" varchar(100) DEFAULT NULL,
  "district" varchar(100) DEFAULT NULL,
  "street" varchar(255) DEFAULT NULL,
  "postal_code" varchar(20) DEFAULT NULL,
  "venue_details" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("location_id"),
  KEY "fk_location_venue" ("venue_id"),
  CONSTRAINT "fk_location_venue" FOREIGN KEY ("venue_id") REFERENCES "venues" ("venue_id") ON DELETE CASCADE
);

-- BASE TABLE `venues`
CREATE TABLE "venues" (
  "venue_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "venue_name" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "venue_address" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "venue_intro" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "intro_source_url" varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "intro_updated_at" datetime DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ("venue_id"),
  UNIQUE KEY "uq_venue_name_addr" ("venue_name","venue_address")
);

-- BASE TABLE `使用者`
CREATE TABLE "使用者" (
  "id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "email" varchar(255) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE KEY "uniq_users_email" ("email")
);

-- BASE TABLE `售票平台`
CREATE TABLE "售票平台" (
  "channel_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "event_id" bigint unsigned NOT NULL,
  "platform" varchar(100) DEFAULT NULL,
  "channel_type" varchar(50) DEFAULT NULL,
  "start_date" date DEFAULT NULL,
  "start_time" time DEFAULT NULL,
  "end_date" date DEFAULT NULL,
  "end_time" time DEFAULT NULL,
  "sales_status" varchar(50) DEFAULT NULL,
  "notes" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("channel_id"),
  KEY "fk_channel_event" ("event_id")
);
