-- BASE TABLE `活動`
CREATE TABLE "活動" (
  "event_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "venue_id" bigint unsigned DEFAULT NULL,
  "來源網站" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "活動名稱" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "藝人" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "搶票時間" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "活動時間" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "活動地點" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "活動地址" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "票價" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "票種" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "網址" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "爬取時間" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "資料來源檔" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("event_id"),
  KEY "idx_events_source" ("來源網站"(64)),
  KEY "idx_events_time" ("活動時間"(64)),
  KEY "idx_events_url" ("網址"(128)),
  KEY "idx_events_venue_id" ("venue_id")
);
