-- BASE TABLE `活動地點`
CREATE TABLE "活動地點" (
  "location_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "venue_id" bigint unsigned NOT NULL,
  "city" varchar(100) DEFAULT NULL,
  "district" varchar(100) DEFAULT NULL,
  "street" varchar(255) DEFAULT NULL,
  "postal_code" varchar(20) DEFAULT NULL,
  "venue_details" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("location_id"),
  KEY "fk_location_venue" ("venue_id")
);

-- VIEW `活動聯合檢視`
CREATE VIEW "活動聯合檢視" AS select "concert_overview"."event_id" AS "event_id","concert_overview"."event_name" AS "活動名稱","concert_overview"."source_site" AS "來源網站","concert_overview"."event_url" AS "網址","concert_overview"."raw_event_time" AS "活動時間","concert_overview"."raw_sale_time" AS "搶票時間","concert_overview"."raw_price" AS "票價","concert_overview"."raw_venue_name" AS "活動地點","concert_overview"."raw_venue_address" AS "活動地址","concert_overview"."venue_id" AS "場地_id","concert_overview"."venue_name" AS "場地名稱","concert_overview"."venue_address" AS "場地地址","concert_overview"."venue_intro" AS "場地介紹","concert_overview"."event_type" AS "活動類型","concert_overview"."price_band" AS "票價區間","concert_overview"."sale_status" AS "售票狀態","concert_overview"."event_segment_confidence" AS "分群信心","concert_overview"."first_performance_date" AS "首場","concert_overview"."last_performance_date" AS "末場","concert_overview"."schedule_count" AS "場次數","concert_overview"."min_price" AS "最低票價","concert_overview"."max_price" AS "最高票價","concert_overview"."price_tier_count" AS "票種數","concert_overview"."artist_count" AS "藝人數","concert_overview"."artist_names" AS "藝人名稱","concert_overview"."artist_regions" AS "藝人地區","concert_overview"."artist_languages" AS "藝人語言","concert_overview"."artist_forms" AS "藝人型態","concert_overview"."event_created_at" AS "活動建立時間" from "concert_overview";

-- BASE TABLE `藝人`
CREATE TABLE "藝人" (
  "artist_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "artist_name" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "artist_intro" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "intro_source_url" varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "intro_updated_at" datetime DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ("artist_id"),
  UNIQUE KEY "uq_artist_name" ("artist_name")
);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_events_ins_to_活動" AFTER INSERT ON "events" FOR EACH ROW REPLACE INTO `活動` (`event_id`,`venue_id`,`來源網站`,`活動名稱`,`藝人`,`搶票時間`,`活動時間`,`活動地點`,`活動地址`,`票價`,`票種`,`網址`,`爬取時間`,`資料來源檔`,`created_at`) VALUES (NEW.`event_id`,NEW.`venue_id`,NEW.`來源網站`,NEW.`活動名稱`,NEW.`藝人`,NEW.`搶票時間`,NEW.`活動時間`,NEW.`活動地點`,NEW.`活動地址`,NEW.`票價`,NEW.`票種`,NEW.`網址`,NEW.`爬取時間`,NEW.`資料來源檔`,NEW.`created_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_events_upd_to_活動" AFTER UPDATE ON "events" FOR EACH ROW REPLACE INTO `活動` (`event_id`,`venue_id`,`來源網站`,`活動名稱`,`藝人`,`搶票時間`,`活動時間`,`活動地點`,`活動地址`,`票價`,`票種`,`網址`,`爬取時間`,`資料來源檔`,`created_at`) VALUES (NEW.`event_id`,NEW.`venue_id`,NEW.`來源網站`,NEW.`活動名稱`,NEW.`藝人`,NEW.`搶票時間`,NEW.`活動時間`,NEW.`活動地點`,NEW.`活動地址`,NEW.`票價`,NEW.`票種`,NEW.`網址`,NEW.`爬取時間`,NEW.`資料來源檔`,NEW.`created_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_events_del_from_活動" AFTER DELETE ON "events" FOR EACH ROW DELETE FROM `活動` WHERE `event_id` = OLD.`event_id`;

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_venue_locations_ins_to_活動地點" AFTER INSERT ON "venue_locations" FOR EACH ROW REPLACE INTO `活動地點` (`location_id`,`venue_id`,`city`,`district`,`street`,`postal_code`,`venue_details`,`created_at`) VALUES (NEW.`location_id`,NEW.`venue_id`,NEW.`city`,NEW.`district`,NEW.`street`,NEW.`postal_code`,NEW.`venue_details`,NEW.`created_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_venue_locations_upd_to_活動地點" AFTER UPDATE ON "venue_locations" FOR EACH ROW REPLACE INTO `活動地點` (`location_id`,`venue_id`,`city`,`district`,`street`,`postal_code`,`venue_details`,`created_at`) VALUES (NEW.`location_id`,NEW.`venue_id`,NEW.`city`,NEW.`district`,NEW.`street`,NEW.`postal_code`,NEW.`venue_details`,NEW.`created_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_venue_locations_del_from_活動地點" AFTER DELETE ON "venue_locations" FOR EACH ROW DELETE FROM `活動地點` WHERE `location_id` = OLD.`location_id`;

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_sales_channels_ins_to_售票平台" AFTER INSERT ON "sales_channels" FOR EACH ROW REPLACE INTO `售票平台` (`channel_id`,`event_id`,`platform`,`channel_type`,`start_date`,`start_time`,`end_date`,`end_time`,`sales_status`,`notes`,`created_at`) VALUES (NEW.`channel_id`,NEW.`event_id`,NEW.`platform`,NEW.`channel_type`,NEW.`start_date`,NEW.`start_time`,NEW.`end_date`,NEW.`end_time`,NEW.`sales_status`,NEW.`notes`,NEW.`created_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_sales_channels_upd_to_售票平台" AFTER UPDATE ON "sales_channels" FOR EACH ROW REPLACE INTO `售票平台` (`channel_id`,`event_id`,`platform`,`channel_type`,`start_date`,`start_time`,`end_date`,`end_time`,`sales_status`,`notes`,`created_at`) VALUES (NEW.`channel_id`,NEW.`event_id`,NEW.`platform`,NEW.`channel_type`,NEW.`start_date`,NEW.`start_time`,NEW.`end_date`,NEW.`end_time`,NEW.`sales_status`,NEW.`notes`,NEW.`created_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_sales_channels_del_from_售票平台" AFTER DELETE ON "sales_channels" FOR EACH ROW DELETE FROM `售票平台` WHERE `channel_id` = OLD.`channel_id`;

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_artists_ins_to_藝人" AFTER INSERT ON "artists" FOR EACH ROW REPLACE INTO `藝人` (`artist_id`,`artist_name`,`artist_intro`,`intro_source_url`,`intro_updated_at`,`created_at`,`updated_at`) VALUES (NEW.`artist_id`,NEW.`artist_name`,NEW.`artist_intro`,NEW.`intro_source_url`,NEW.`intro_updated_at`,NEW.`created_at`,NEW.`updated_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_artists_upd_to_藝人" AFTER UPDATE ON "artists" FOR EACH ROW REPLACE INTO `藝人` (`artist_id`,`artist_name`,`artist_intro`,`intro_source_url`,`intro_updated_at`,`created_at`,`updated_at`) VALUES (NEW.`artist_id`,NEW.`artist_name`,NEW.`artist_intro`,NEW.`intro_source_url`,NEW.`intro_updated_at`,NEW.`created_at`,NEW.`updated_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_artists_del_from_藝人" AFTER DELETE ON "artists" FOR EACH ROW DELETE FROM `藝人` WHERE `artist_id` = OLD.`artist_id`;

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_users_ins_to_使用者" AFTER INSERT ON "users" FOR EACH ROW REPLACE INTO `使用者` (`id`,`email`,`password_hash`,`created_at`,`updated_at`) VALUES (NEW.`id`,NEW.`email`,NEW.`password_hash`,NEW.`created_at`,NEW.`updated_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_users_upd_to_使用者" AFTER UPDATE ON "users" FOR EACH ROW REPLACE INTO `使用者` (`id`,`email`,`password_hash`,`created_at`,`updated_at`) VALUES (NEW.`id`,NEW.`email`,NEW.`password_hash`,NEW.`created_at`,NEW.`updated_at`);

CREATE DEFINER="avnadmin"@"%" TRIGGER "tr_users_del_from_使用者" AFTER DELETE ON "users" FOR EACH ROW DELETE FROM `使用者` WHERE `id` = OLD.`id`;
